const { Client, Collection } = require('discord.js');
const db = require('./database/models/Database');

class Product extends Collection
  async static async findOne(query)
    const result = await db.get('produtos', query);
    return result ? new Product(result) : null;
  }

  async static async save(product)
    await db.set('produtos', product._id, product);
  }
